// Runs the same inputs through the Home row card helpers and writes every
// result to $PARITY_OUT as JSON. run.sh runs it once against this branch and
// once against the old home_screen.dart, then compares the two files.
// facade.dart is generated by run.sh.
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:get_it/get_it.dart';
import 'package:jellyfin_preference/jellyfin_preference.dart';
import 'package:moonfin/data/models/aggregated_item.dart';
import 'package:moonfin/data/models/home_row.dart';
import 'package:moonfin/data/repositories/tmdb_repository.dart';
import 'package:moonfin/data/services/plugin_sync_service.dart';
import 'package:moonfin/preference/preference_constants.dart';
import 'package:moonfin/preference/user_preferences.dart';
import 'package:server_core/server_core.dart' show ImageApi;
import 'package:shared_preferences/shared_preferences.dart';

import 'facade.dart';

class _EchoApi implements ImageApi {
  String _q(Map<String, Object?> m) =>
      m.entries.where((e) => e.value != null).map((e) => '${e.key}=${e.value}').join('&');
  @override
  String getPrimaryImageUrl(String id, {int? maxWidth, int? maxHeight, String? tag}) =>
      'P/$id?${_q({'w': maxWidth, 'h': maxHeight, 't': tag})}';
  @override
  String getBackdropImageUrl(String id, {int? maxWidth, int? index, String? tag}) =>
      'B/$id?${_q({'w': maxWidth, 'i': index, 't': tag})}';
  @override
  String getLogoImageUrl(String id, {int? maxWidth, String? tag}) =>
      'L/$id?${_q({'w': maxWidth, 't': tag})}';
  @override
  String getBannerImageUrl(String id, {int? maxWidth, String? tag}) =>
      'N/$id?${_q({'w': maxWidth, 't': tag})}';
  @override
  String getThumbImageUrl(String id, {int? maxWidth, String? tag}) =>
      'T/$id?${_q({'w': maxWidth, 't': tag})}';
  @override
  noSuchMethod(Invocation invocation) => super.noSuchMethod(invocation);
}

class _FakeSync implements PluginSyncService {
  @override
  bool get tmdbThumbsAvailable => false;
  @override
  noSuchMethod(Invocation invocation) => super.noSuchMethod(invocation);
}

/// Every combination of optional raw fields that the resolvers read.
List<AggregatedItem> _items() {
  final out = <AggregatedItem>[];
  const types = [
    'Movie', 'Series', 'Season', 'Episode', 'Video', 'MusicVideo',
    'MusicAlbum', 'MusicArtist', 'Audio', 'Playlist', 'Person', 'Genre',
    'MusicGenre', 'Studio', 'Network', 'TvChannel', 'LiveTvChannel',
    'CollectionFolder', 'BoxSet', null,
  ];
  final variants = <String, Map<String, Object?>>{
    'none': {},
    'primary': {'ImageTags': {'Primary': 'p'}},
    'thumb': {'ImageTags': {'Thumb': 'th'}},
    'banner': {'ImageTags': {'Banner': 'bn'}},
    'logo': {'ImageTags': {'Logo': 'lg'}},
    'all': {
      'ImageTags': {'Primary': 'p', 'Thumb': 'th', 'Banner': 'bn', 'Logo': 'lg'},
      'BackdropImageTags': ['bd'],
    },
    'backdrop': {'BackdropImageTags': ['bd']},
    'series': {
      'SeriesId': 'ser', 'SeriesPrimaryImageTag': 'sp',
      'SeriesImageTags': {'Banner': 'sbn'},
    },
    'seriesNoTag': {'SeriesId': 'ser'},
    'seriesPrimaryOnly': {'SeriesId': 'ser', 'SeriesPrimaryImageTag': 'sp'},
    'parentPrimary': {'ParentPrimaryImageItemId': 'pp', 'ParentPrimaryImageTag': 'ppt'},
    'parentThumb': {'ParentThumbItemId': 'pth', 'ParentThumbImageTag': 'ptt'},
    'parentBackdrop': {'ParentBackdropItemId': 'pbd', 'ParentBackdropImageTags': ['pbt']},
    'parents': {
      'SeriesId': 'ser', 'SeriesPrimaryImageTag': 'sp',
      'ParentPrimaryImageItemId': 'pp', 'ParentPrimaryImageTag': 'ppt',
      'ParentThumbItemId': 'pth', 'ParentThumbImageTag': 'ptt',
      'ParentBackdropItemId': 'pbd', 'ParentBackdropImageTags': ['pbt'],
    },
    'rep': {'PrimaryImageItemId': 'rep', 'PrimaryImageTag': 'rpt'},
    'repWide': {
      'PrimaryImageItemId': 'rep', 'PrimaryImageTag': 'rpt',
      'PrimaryImageAspectRatio': 1.5, 'ImageTags': {'Primary': 'p'},
    },
    'repTall': {
      'PrimaryImageItemId': 'rep', 'PrimaryImageTag': 'rpt',
      'PrimaryImageAspectRatio': 0.67, 'ImageTags': {'Primary': 'p'},
    },
    'wide': {'PrimaryImageAspectRatio': 1.78, 'ImageTags': {'Primary': 'p'}},
    'studioLogo': {studioLogoUrlKey: 'https://logo/x.png', 'ImageTags': {'Primary': 'p'}},
  };
  for (final type in types) {
    for (final v in variants.entries) {
      out.add(AggregatedItem(
        id: '${type}_${v.key}',
        serverId: 'srv',
        rawData: {'Id': '${type}_${v.key}', if (type != null) 'Type': type, ...v.value},
      ));
    }
  }
  // Seerr items.
  final seerr = <String, Map<String, Object?>>{
    'none': {},
    'poster': {'PosterPath': '/poster.jpg'},
    'backdrop': {'BackdropPath': '/bd.jpg'},
    'both': {'PosterPath': '/poster.jpg', 'BackdropPath': 'https://full/bd.jpg'},
    'emptyPath': {'PosterPath': '', 'BackdropPath': ''},
  };
  for (final mt in ['movie', 'tv', 'person', null]) {
    for (final v in seerr.entries) {
      for (final id in ['12345', 'abc']) {
        out.add(AggregatedItem(
          id: id,
          serverId: 'seerr',
          rawData: {
            'Id': id, 'Type': 'Movie', if (mt != null) 'SeerrMediaType': mt,
            'ProviderIds': {'Tmdb': '777'}, ...v.value,
          },
        ));
      }
    }
  }
  return out;
}

String _k(AggregatedItem i) => '${i.serverId}/${i.id}/${i.rawData['SeerrMediaType']}/${jsonEncode(i.rawData)}';

List<HomeRow> _rows(List<AggregatedItem> music, List<AggregatedItem> mixed) => [
  for (final t in HomeRowType.values) ...[
    HomeRow(id: t.name, title: 't', rowType: t),
    HomeRow(id: '${t.name}_lib1', title: 't', rowType: t),
    HomeRow(id: t.name, title: 't', rowType: t, isAudio: true),
    HomeRow(id: 'x', title: 't', rowType: t, items: music),
    HomeRow(id: 'x', title: 't', rowType: t, items: mixed),
  ],
  for (final id in [
    'seerr_shortcuts', 'seerr_movie_genres', 'seerr_series_genres',
    'seerr_studios', 'seerr_networks', 'mdblist_watching_now', 'studios',
    'latest_lib1', 'latest_srv_lib1', 'recently_released_lib1',
    'favorites_movies', 'favorites_series', 'favorites_episodes',
    'favorites_people', 'favorites_artists', 'favorites_musicvideos',
    'favorites_albums', 'favorites_songs', 'libraryTiles', 'resume',
    'nextUp', 'collections', 'genres', 'playlists', 'audioAlbums',
  ])
    for (final t in [HomeRowType.pluginDynamic, HomeRowType.studios, HomeRowType.latestMedia, HomeRowType.favorites, HomeRowType.libraryTiles])
      HomeRow(id: id, title: 't', rowType: t),
];

Future<UserPreferences> _prefs(Map<String, Object> values) async {
  SharedPreferences.setMockInitialValues(values);
  final store = PreferenceStore();
  await store.init();
  return UserPreferences(store);
}

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  test('dump', () async {
    GetIt.instance.registerSingleton<PluginSyncService>(_FakeSync());
    final api = _EchoApi();
    final out = <String, String?>{};
    final items = _items();
    final music = [
      for (final t in ['Audio', 'MusicAlbum', 'MusicArtist'])
        AggregatedItem(id: t, serverId: 'srv', rawData: {'Type': t}),
    ];
    final mixed = [...music, const AggregatedItem(id: 'm', serverId: 'srv', rawData: {'Type': 'Movie'})];
    final rows = _rows(music, mixed);

    for (final item in items) {
      final k = _k(item);
      for (final type in ImageType.values) {
        for (final h in [88.0, 150.0, 210.5]) {
          for (final s in [false, true]) {
            for (final r in [1.0, 1.5, 2.0]) {
              for (final m in [false, true]) {
                out['row|$k|$type|$h|$s|$r|$m'] = fRowUrl(item, api, h, type, s, r, m);
              }
            }
          }
        }
        for (final row in rows) {
          out['aspect|$k|${row.id}|${row.rowType}|${row.isAudio}|${row.items.length}|$type'] =
              fAspect(item, row, type).toString();
        }
      }
      for (final mh in [null, 200]) {
        for (final mw in [null, 356]) {
          out['primary|$k|$mh|$mw'] = fPrimary(item, api, mh, mw);
        }
      }
      for (final t in ['Primary', 'Thumb', 'Banner', 'Logo', 'Backdrop']) {
        out['tag|$k|$t'] = fTag(item, t);
      }
    }
    for (final p in [null, '', '/a.jpg', 'http://x/y.jpg', 'https://x/y.jpg', 'relative.jpg']) {
      for (final w in [300, 1280]) {
        out['tmdb|$p|$w'] = fTmdb(p, w);
      }
    }

    final prefSets = <String, Map<String, Object>>{
      'default': {},
      'v1': {'pref_home_rows_style': 'v1'},
      'v2': {'pref_home_rows_style': 'v2'},
      'v2-noMyMediaCards': {'pref_home_rows_style': 'v2', 'pref_modern_cards_my_media': false},
      'v2-myMediaCards': {'pref_home_rows_style': 'v2', 'pref_modern_cards_my_media': true},
      'override-banner': {'homeRowsUniversalOverride': true, 'homeRowsUniversalImageType': 'banner'},
      'override-poster': {'homeRowsUniversalOverride': true, 'homeRowsUniversalImageType': 'poster'},
    };
    for (final ps in prefSets.entries) {
      final prefs = await _prefs(ps.value);
      for (final type in HomeSectionType.values) {
        if (type == HomeSectionType.none) continue;
        await prefs.set(UserPreferences.homeRowImageType(type), ImageType.values[type.index % 3]);
      }
      for (final row in rows) {
        final rk = '${ps.key}|${row.id}|${row.rowType}|${row.isAudio}|${row.items.length}';
        out['imageType|$rk'] = fImageType(row, prefs).toString();
        out['modern|$rk'] = fModern(row, prefs).toString();
        out['static|$rk'] = fStatic(row, prefs).toString();
        out['seerr|$rk'] = fSeerr(row).toString();
      }
      // Also with untouched per-section defaults.
      final fresh = await _prefs(ps.value);
      for (final row in rows) {
        out['imageTypeDefault|${ps.key}|${row.id}|${row.rowType}|${row.isAudio}|${row.items.length}'] =
            fImageType(row, fresh).toString();
      }
    }

    File(Platform.environment['PARITY_OUT']!).writeAsStringSync(jsonEncode(out));
    // ignore: avoid_print
    print('cases: ${out.length}, non-null: ${out.values.where((v) => v != null).length}');
  });
}
